package erratum

import "errors"

// Use opens a resource via the given opener, calls Frob(input) on it and
// makes sure the resource is closed exactly once, no matter what happens.
//
// - If the opener fails with a TransientError it keeps retrying; any other
//   error is returned.
// - If Frob panics with a FrobError, Defrob is called with the FrobError's
//   defrobTag and the FrobError is returned. If Frob panics with some other
//   error, that error is returned. In both cases the resource is closed.
func Use(opener ResourceOpener, input string) error {
	var resource Resource
	var err error
	for {
		resource, err = opener()
		if err == nil {
			break
		}
		var te TransientError
		if errors.As(err, &te) {
			// Resource is temporarily unavailable, retry.
			continue
		}
		return err
	}

	// Registered last, so it runs first on unwind: recover from any panic
	// from Frob (and possibly Defrob) before the resource is closed.
	defer func() {
		r := recover()
		if r == nil {
			return
		}
		switch e := r.(type) {
		case FrobError:
			resource.Defrob(e.defrobTag)
			err = e
		case error:
			err = e
		default:
			// Not an error of any kind; keep the panic going.
			panic(r)
		}
	}()

	// Registered first, so it runs last on unwind: the resource is closed
	// exactly once after any recovery above.
	defer resource.Close()

	resource.Frob(input)
	return err
}

