package erratum

import "errors"

// Use opens a resource via the given opener, calls Frob(input) on it and
// makes sure the resource is closed exactly once, no matter what happens.
//
// - If the opener fails with a TransientError it keeps retrying; any other
//   error is returned.
// - If Frob panics with a FrobError, Defrob is called with the FrobError's
//   defrobTag (before the resource is closed) and the FrobError is returned.
//   If Frob panics with some other error value, that error is returned.
func Use(opener ResourceOpener, input string) (err error) {
	var resource Resource
	for {
		resource, err = opener()
		if err == nil {
			break
		}
		var te TransientError
		if errors.As(err, &te) {
			// Resource is temporarily unavailable, retry.
			continue
		}
		return err
	}

	// Registered first, so it runs last on unwind: the resource is closed
	// exactly once, after any recovery below.
	defer resource.Close()

	// Registered last, so it runs first on unwind: recover from any panic
	// coming out of Frob and turn it into the returned error. A named
	// return value is required here, because the "return err" below is
	// never evaluated when Frob panics.
	defer func() {
		r := recover()
		if r == nil {
			return
		}
		switch e := r.(type) {
		case FrobError:
			resource.Defrob(e.defrobTag)
			err = e
		case error:
			err = e
		default:
			// Not an error of any kind; keep the panic going.
			panic(r)
		}
	}()

	resource.Frob(input)
	return err
}

